<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_permission('print_location_labels');$ids=is_super_admin()?[]:assigned_location_ids();$params=[];$sql='SELECT id,code,name,warehouse,floor_name,section_name,rack,shelf_bin FROM locations WHERE active=1';if(!is_super_admin()){if(!$ids)$sql.=' AND 1=0';else{$ph=implode(',',array_fill(0,count($ids),'?'));$sql.=" AND id IN ($ph)";$params=$ids;}}$sql.=' ORDER BY code';$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();page_header('Rack / Bin Barcode Labels'); ?>
<div class="no-print actions"><button class="btn" onclick="print()">Print Rack/Bin Labels</button></div><br><div id="labels" class="labels"></div><style>.labels{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}.label{border:2px solid #222;padding:12px;text-align:center;break-inside:avoid}.label .code{font-size:20px;font-weight:900}.label svg{max-width:100%;height:70px}@media print{.labels{grid-template-columns:repeat(2,1fr);gap:5px}.label{padding:6px}}</style>
<script>const patterns=['212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312113','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'];function code128Svg(text){let vals=[104],sum=104;for(let i=0;i<text.length;i++){let c=text.charCodeAt(i);if(c<32||c>126)c=63;let v=c-32;vals.push(v);sum+=v*(i+1);}vals.push(sum%103,106);let x=10,bars='';for(const v of vals){const p=patterns[v];for(let i=0;i<p.length;i++){const w=parseInt(p[i])*2;if(i%2===0)bars+=`<rect x="${x}" y="0" width="${w}" height="50"/>`;x+=w;}}return `<svg viewBox="0 0 ${x+10} 68" xmlns="http://www.w3.org/2000/svg">${bars}<text x="${(x+10)/2}" y="65" font-size="11" text-anchor="middle">${text.replace(/&/g,'&amp;').replace(/</g,'&lt;')}</text></svg>`;}const data=<?=json_encode($rows,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;let h='';for(const l of data){h+=`<div class="label"><div><b>PRATYANGI FASHIONS</b></div><div class="code">${l.code}</div>${code128Svg(l.code)}<div>${l.warehouse||''} · Floor ${l.floor_name||'-'} · ${l.section_name||''}</div><div><b>Rack ${l.rack||'-'} · Bin ${l.shelf_bin||'-'}</b></div></div>`;}document.getElementById('labels').innerHTML=h;</script><?php page_footer();
